import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create plane geometry for the pricing card
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Load the brushed metal texture
  let textureResource = null;

  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
  });

  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene position from config
  if (config.scenePosition) {
    mesh.position.copy(config.scenePosition);
  }

  // Load and apply the brushed metal texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      textureResource = tex;
      tex.colorSpace = THREE.SRGBColorSpace;
      material.map = tex;
      material.needsUpdate = true;
    }).catch((err) => {
      console.warn('[pricing-card-2] Failed to load metal texture:', err);
    });
  }

  // Setup cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (textureResource) {
      textureResource.dispose();
    }
  };

  // No event handlers needed for static composition
  mesh.userData.handlers = {};

  return mesh;
}
